/*
 * third_party/libepoxy-port/config.h — libepoxy's build configuration,
 * written by hand instead of generated by meson.
 *
 * Upstream builds with meson, which writes this file from the options it
 * was given. This system compiles libepoxy with the main Makefile, the
 * same cross compiler and the same flags as everything else in ring 3,
 * so the handful of things meson would have decided are decided here.
 *
 * ---- every window system is off, and that is the whole file ----
 *
 * GLX is OpenGL over the X11 protocol. EGL is the binding between OpenGL
 * and a native window system. WGL is Microsoft's. This machine has none
 * of the three: there is no X server, no Wayland compositor, no EGL
 * implementation and no Windows. Leaving them on would compile three
 * dispatch tables whose every entry resolves to nothing, and — worse —
 * would pull in <X11/Xlib.h> and <EGL/egl.h>, neither of which exists in
 * this tree.
 *
 * What is left is the desktop-GL dispatch table, which is the part
 * WebKit's find_package actually wants and the part that can be given a
 * truthful answer: entry points are resolved through dlsym, and
 * libc/dlfcn.c answers from a table this system registers. See
 * third_party/libepoxy-port/vxgl.c for what is in that table and the
 * long note there about what a framebuffer can and cannot honestly
 * implement.
 */

#ifndef VX_EPOXY_CONFIG_H
#define VX_EPOXY_CONFIG_H

#define ENABLE_GLX 0
#define ENABLE_EGL 0
#define ENABLE_X11 0

/*
 * ---- EPOXY_PUBLIC is deliberately NOT defined here ----
 *
 * The obvious thing was to define it empty, on the reasoning that there
 * is no shared object for a symbol to be exported from and so no
 * visibility attribute worth applying. That was wrong, and the way it
 * failed is worth recording.
 *
 * include/epoxy/common.h defaults it to `extern` under an #ifndef.
 * Every one of the two thousand dispatch pointers is declared
 * `EPOXY_PUBLIC void (*epoxy_glAccum)(...)` in the generated header —
 * so with the default it is a *declaration*, and with an empty
 * definition it becomes a **tentative definition** in every translation
 * unit that includes it. GCC 10 and later default to -fno-common, so
 * two tentative definitions of one name are two definitions, and the
 * link ended in some two thousand lines of
 *
 *     multiple definition of `epoxy_glAccum'
 *
 * which reads like a broken library and was a one-line mistake in this
 * file. Leaving it undefined lets common.h's own default apply, which
 * is what upstream does for a static build.
 */

/* The Khronos platform header ships inside libepoxy's own include tree,
 * so it is always found and never has to come from the system. */
#define HAVE_KHRPLATFORM_H 1

/* meson's name for "this is not Windows and not macOS". */
#define BUILD_IN_DLL 0

#endif /* VX_EPOXY_CONFIG_H */
